<?php require_once __DIR__.'/../config/config.php';require_admin();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM students WHERE id=?');$st->execute([$id]);$r=$st->fetch();if(!$r)die('دانش‌آموز پیدا نشد.');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{$photo=$r['photo'];if(!empty($_FILES['photo']['name'])&&is_uploaded_file($_FILES['photo']['tmp_name'])){$ext=strtolower(pathinfo($_FILES['photo']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['jpg','jpeg','png','webp'],true))throw new Exception('فرمت عکس درست نیست.');$photo=uniqid('student_',true).'.'.$ext;move_uploaded_file($_FILES['photo']['tmp_name'],__DIR__.'/../uploads/'.$photo);}$pdo->prepare('UPDATE students SET student_code=?,first_name=?,father_name=?,guardian_phone=?,course_type=?,class_level=?,study_time=?,photo=? WHERE id=?')->execute([trim($_POST['student_code']),trim($_POST['first_name']),trim($_POST['father_name']),trim($_POST['guardian_phone']),$_POST['course_type'],trim($_POST['class_level']),$_POST['study_time'],$photo,$id]);header('Location:index.php');exit;}catch(Exception $e){$err=$e->getMessage();}}require '../partials/header.php';?><div class="panel form-panel"><h2>ویرایش دانش‌آموز</h2><?php if($err):?><div class="alert"><?=h($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><div class="row"><label>شماره ID<input required name="student_code" value="<?=h($r['student_code'])?>"></label><label>نام<input required name="first_name" value="<?=h($r['first_name'])?>"></label><label>نام پدر<input name="father_name" value="<?=h($r['father_name'])?>"></label><label>شماره ولی دانش‌آموز<input required name="guardian_phone" value="<?=h($r['guardian_phone'])?>"></label><label>نوع صنف *<select name="course_type" required><option <?=$r['course_type']==='صنف درسی'?'selected':''?>>صنف درسی</option><option <?=$r['course_type']==='حرفه خیاطی'?'selected':''?>>صنف حرفه‌ای خیاطی</option></select></label><label>درجه صنف<input name="class_level" value="<?=h($r['class_level'])?>"></label><label>تایم<select name="study_time"><option <?=$r['study_time']==='تایم اول'?'selected':''?>>تایم اول</option><option <?=$r['study_time']==='تایم دوم'?'selected':''?>>تایم دوم</option></select></label><label>عکس جدید<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label></div><button>ذخیره تغییرات</button> <a class="btn secondary" href="../cards/student.php?id=<?=$id?>">کارت</a></form></div><?php require '../partials/footer.php';?>
